import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSpace } from "../handlers/updateSpace";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateSpaceRequest } from "../types/UpdateSpaceRequest";

type Data = Awaited<ReturnType<typeof updateSpace>>;
type Vars = { spaceId: SpacePartition; req: UpdateSpaceRequest };

export function useUpdateSpace(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSpace(vars.spaceId, vars.req),
    ...options,
  });
}
